import { type Toast as ToastController, type ToastItem as ToastMessage } from "@cssints/headless";
import {
  type ConfigEvent,
  createMachine,
  defineMachine,
  type EffectHandle,
  type Machine,
  type TransitionList,
} from "@cssints/machine";
import { createMachineStore } from "@cssints/machine/solid";
import { Portal } from "@solidjs/web";
import type { JSX } from "@solidjs/web";
import * as css from "cssints" with { type: "cssints" };
import { createEffect, For, merge, onCleanup, Show } from "solid-js";

import { type PartProps, renderPart, type Render, type Renderable } from "./render.tsx";
import { t } from "./theme.ts" with { type: "cssints" };

/** One row's phases: the box entering, at rest, on its way out, and the step past it that unmounts the row. */
export type ToastPhase = "entering" | "visible" | "leaving" | "gone";

/** How long a row's enter and leave take when the motion preference allows one. */
export const TOAST_ENTER_MS = 160;
export const TOAST_LEAVE_MS = 120;

/** The row machine's context: the motion preference it was built with. */
export interface ToastRowContext {
  readonly reduced: boolean;
}

// a type alias, not an interface: `PayloadMap` is an index signature, and only an alias is assignable to one
type ToastRowPayloads = {
  readonly dismiss: undefined;
  readonly finish: { readonly id: number };
};

/** The row machine's events: a dismissal, and the completion of the animation an effect started. */
export type ToastRowEvent =
  | { readonly type: "dismiss" }
  | { readonly type: "finish"; readonly id: number };

type ToastRowMachine = Machine<ToastRowContext, ToastPhase, ToastRowEvent>;

type Config = ConfigEvent<ToastRowPayloads>;

// A dismissal lands at once for a reader who asked for no motion, and otherwise runs the leave effect. There is no
// debounce: `leaving` accepts no `dismiss`, so the second intent of a burst — the timeout after the close button, or a
// second click — is dropped by the state the first one entered, and the leave is neither restarted nor delayed.
const leave = (reduced: boolean): TransitionList<ToastRowContext, Config> =>
  reduced ? { target: "gone" } : { target: "leaving", effect: { type: "leave" } };

/**
 * The row's lifecycle: `entering` (the enter effect runs) → `visible` → `leaving` (the leave effect runs) → `gone`. A
 * `dismiss` in `entering` leaves from the phase it is in, so the box reverses from where it is; a `finish` that carries a
 * cancelled effect's id is dropped by the machine, never by this component. `gone` is the row's last state: the stack
 * removes it and the primitive finally dismisses the toast.
 */
export const toastRowMachine = (reduced: boolean) =>
  defineMachine<ToastRowPayloads>()({
    start: reduced ? "visible" : "entering",
    initial: { reduced },
    states: {
      entering: {
        effect: [{ type: "enter" }],
        on: {
          dismiss: leave(reduced),
          finish: { target: "visible" },
        },
      },
      visible: {
        on: {
          dismiss: leave(reduced),
        },
      },
      leaving: {
        on: {
          finish: { target: "gone" },
        },
      },
      gone: {},
    },
  });

/** What the region's `render` gets: the landmark's props, `data-part` and the caller's class merged in. */
export type ToasterPartProps = PartProps;

/** What one row's `render` gets: the live region's props, `data-part`, the tone, and the caller's class. */
export type ToastPartProps = PartProps;

export interface ToasterProps extends Renderable<ToasterPartProps, void> {
  /** The queue the page holds: `createToast()` from `@cssints/headless`. */
  readonly toast: ToastController;
  /** The element the stack is portalled into (default `document.body`), for a host with its own overlay root. */
  readonly mount?: Element;
  /** One row's element, for every toast: the item part's `render`, passed down. */
  readonly renderItem?: Render<ToastPartProps, ToastMessage> | undefined;
  /** The motion preference; left out, `prefers-reduced-motion: reduce` is read once, when a row is created. */
  readonly reducedMotion?: boolean | undefined;
  readonly class?: string;
}

export interface ToastProps extends Renderable<ToastPartProps, ToastMessage> {
  readonly toast: ToastController;
  /** The toast the primitive queued: its title, description, tone and id. */
  readonly item: ToastMessage;
  readonly reducedMotion?: boolean | undefined;
  readonly class?: string;
}

// The stack sits in the viewport's bottom end corner and never takes a click of its own: with nothing in the queue it is an
// empty, still box over the page, so it is transparent to the pointer and each row turns it back on. The corner is the
// inline end of the writing mode, and the inset is a token so a dense screen grows it with everything else.
const regionClass = css.cn(
  css.position("fixed"),
  css.insetBlockEnd(t.space._4),
  css.insetInlineEnd(t.space._4),
  // `z-index` takes an `<integer>`, which a `number` token is not: the class reads the token by hand, as the dialog's layer
  css.zIndex("var(--z-toast)"),
  css.display("flex"),
  css.flexDirection("column"),
  css.alignItems("stretch"),
  css.gap(t.space._2),
  css.width("min(24rem, calc(100vw - 2 * 16px))"),
  css.pointerEvents("none"),
);

// The row is painted at rest and its phases are the machine's: `entering` starts transparent, `leaving` is headed to
// transparent, and the WAAPI animation the machine's effect runs covers the way between the row's own opacity and the
// state's. The CSS is the animation's ends, so a row with no animation (reduced motion, or a frame before it starts) is
// already at the right end and never flashes.
//
// The tone is one rule on the leading edge: the theme has an invalid colour and one accent, so `success` takes the accent
// and `info` the plain border. The row names the tone it was queued with (`data-tone`), which is the primitive's own
// `item.tone`; the `error` row is also `role="alert"`, and the title follows it through `within()`.
const toast = css.cv({
  base: css.cn(
    // the marker `within()` reads, so a part inside the row can follow the tone without a prop of its own
    css.group("toast"),
    css.pointerEvents("auto"),
    css.display("grid"),
    css.gridTemplateColumns("minmax(0, 1fr) auto"),
    css.gridTemplateAreas('"title close" "description close"'),
    css.columnGap(t.space._2),
    css.alignItems("start"),
    css.boxSizing("border-box"),
    css.padding(t.space._3),
    css.border("1px solid", "transparent"),
    css.borderInlineStartWidth(t.space._1),
    css.borderRadius(t.radius.lg),
    css.bg(t.color.overlayBackground),
    css.color(t.color.text),
    css.boxShadow(t.shadow.popover),
    css.fontSize(t.font.size),
    // `visible` is the resting look; the two transient phases are the animation's ends, and `gone` is never painted
    css.attr("data-state", "entering")(css.opacity(0)),
    css.attr("data-state", "leaving")(css.opacity(0)),
  ),
  variants: {
    tone: {
      info: css.cn(css.borderInlineStartColor(t.color.border)),
      success: css.cn(css.borderInlineStartColor(t.color.highlight)),
      error: css.cn(css.borderInlineStartColor(t.color.invalid)),
    },
  },
  defaultVariants: { tone: "info" },
});

const titleClass = css.cn(
  css.gridArea("title"),
  css.margin("0"),
  css.fontWeight("500"),
  css.lineHeight(1.4),
  css.overflowWrap("anywhere"),
  css.within(css.attr("data-tone", "error"), "toast")(css.color(t.color.invalid)),
);

const descriptionClass = css.cn(
  css.gridArea("description"),
  css.margin("0"),
  css.color(t.color.muted),
  css.lineHeight(1.5),
  css.overflowWrap("anywhere"),
);

// A glyph with a label, as the primitive's docs ask: `aria-atomic` reads the row's whole text, and a whole word here would
// be announced with every message. The label stays short for the same reason.
const closeClass = css.cn(
  css.gridArea("close"),
  css.appearance("none"),
  css.display("inline-flex"),
  css.alignItems("center"),
  css.justifyContent("center"),
  css.width(t.space._6),
  css.height(t.space._6),
  css.margin("0"),
  css.padding("0"),
  css.border("none"),
  css.borderRadius(t.radius.sm),
  css.bg("transparent"),
  css.color(t.color.muted),
  css.fontSize(t.font.sizeLg),
  css.lineHeight(1),
  css.cursor("pointer"),
  css.hover(css.bg(t.color.buttonBackground), css.color(t.color.text)),
  css.focusVisible(css.outline("2px solid", t.color.focusRing), css.outlineOffset("2px")),
);

/**
 * APG alert / status, styled as a stack: `createToast` owns the queue, one timer per toast, the hover and focus pause, the
 * ceiling and the live region each row is; `Toaster` is the `role="region"` landmark those rows live in, portalled into
 * `document.body` (or `mount`) so a `transform` or `overflow` ancestor can neither clip the stack nor become the
 * containing block of its `position: fixed`.
 *
 * The page holds the controller (`const toast = createToast()`), pushes with `toast.show(...)` and renders one
 * `<Toaster toast={toast} />`; the stack is always in the DOM and empty when there is nothing to say. The queue's
 * countdown asks the row to leave (`onDismissRequest`) rather than removing it, so the row animates out and the primitive
 * dismisses it only when the machine reaches `gone`; `toast.dismiss(id)` still removes at once, and a paused countdown is
 * the row's `:hover` / `:focus-within`, not a class.
 */
export const Toaster = (props: ToasterProps): JSX.Element => {
  // `tabindex="-1"`: the region is the F6 target the primitive's docs describe, focusable by the host's handler and not a
  // stop of the page's tab order.
  const own = {
    "data-part": "toast-region",
    tabindex: "-1",
    get class() {
      return css.cn(regionClass, props.class);
    },
  } as PartProps;
  return renderPart(props, merge(props.toast.regionProps, own), undefined, (part) => (
    <Portal mount={props.mount}>
      <div {...part}>
        <For each={props.toast.toasts()}>
          {(item) => (
            <Toast
              toast={props.toast}
              item={item}
              render={props.renderItem}
              reducedMotion={props.reducedMotion}
            />
          )}
        </For>
      </div>
    </Portal>
  ));
};

const prefersReducedMotion = (): boolean =>
  typeof window !== "undefined" &&
  typeof window.matchMedia === "function" &&
  window.matchMedia("(prefers-reduced-motion: reduce)").matches;

/** The animation a row is running, with the handle the machine issued for it. */
interface LiveRow {
  readonly handle: EffectHandle;
  readonly animation: Animation;
  readonly element: HTMLElement;
}

/**
 * One toast: the `role` and `aria-atomic` the primitive gives it (`role="alert"` for `error`, `status` otherwise), the
 * `data-tone` it was queued with, and the title, the optional description and a close button. Hover and focus pause the
 * countdown through the handlers `toastProps` hands over.
 *
 * The row's phase is `@cssints/machine`'s: `entering` runs the enter animation, a `dismiss` in it reverses from the
 * opacity the box has reached (the leave effect reads it before the enter is cancelled), a `dismiss` in `leaving` is a
 * state the machine does not react to so the leave is never restarted, and a cancelled animation's own completion carries
 * a dead handle id and is dropped. `prefers-reduced-motion` builds the machine at `visible`, so a dismissal goes straight
 * to `gone` and no animation exists to skip. `data-state` and `hidden` read the row's own store, so one row's phase never
 * re-runs another row's readers.
 */
export const Toast = (props: ToastProps): JSX.Element => {
  // the preference is read once per row: a toast lives for seconds, and a machine is not rebuilt under a running effect
  const reduced = props.reducedMotion ?? prefersReducedMotion();
  const machine: ToastRowMachine = createMachine(toastRowMachine(reduced), { autoStart: false });
  const store = createMachineStore(machine);
  // the pair the Atomic rule is about: both read this row's phase, and only a change of the derived value notifies
  const view = store.projection(
    (draft, from) => {
      draft.hidden = from.phase === "gone";
    },
    { hidden: false },
  );

  let row: HTMLElement | undefined;
  /** The running animation, or `undefined` at rest. */
  let live: LiveRow | undefined;
  /** The opacity a cancelled enter had reached: where the leave starts. */
  let carried: number | undefined;

  const offEffect = machine.onEffect((handle) => {
    const element = row;
    if (element === undefined) {
      // a host's `render` that took no ref: there is nothing to animate, so the row lands in the next task
      queueMicrotask(() => machine.send({ type: "finish", id: handle.id }));
      return;
    }
    const entering = handle.spec.type === "enter";
    const from = entering ? 0 : (carried ?? 1);
    carried = undefined;
    const animation = element.animate([{ opacity: from }, { opacity: entering ? 1 : 0 }], {
      duration: entering ? TOAST_ENTER_MS : TOAST_LEAVE_MS,
      easing: "ease-out",
      // each phase's end is the state's own styling; the leave holds its end until `gone` unmounts the row
      fill: entering ? "both" : "forwards",
    });
    live = { handle, animation, element };
    const done = (): void => {
      if (live?.handle.id === handle.id) {
        live = undefined;
      }
      // drop the fill hold so the state's own styling is what paints, then report the completion
      animation.cancel();
      // a completion, and a cancelled animation's own rejection: the machine drops the latter by its dead id
      machine.send({ type: "finish", id: handle.id });
    };
    animation.finished.then(done, done);
  });

  const offCancel = machine.onCancel((handle) => {
    if (live?.handle.id !== handle.id) {
      return;
    }
    const cancelled = live;
    live = undefined;
    // the box's own opacity, whatever the easing: the leave starts where the enter was, not at its end
    const opacity = Number.parseFloat(getComputedStyle(cancelled.element).opacity);
    carried = Number.isNaN(opacity) ? 1 : opacity;
    cancelled.animation.cancel();
  });

  // The countdown is the primitive's; its expiry is this row's `dismiss`, in the same frame as a close click. The row
  // claims the request by id, so a request that arrives before it mounted leaves the toast to the primitive.
  const offRequest = props.toast.onDismissRequest((id) => {
    if (id !== props.item.id) {
      return false;
    }
    machine.send({ type: "dismiss" });
    return true;
  });

  // The row is hidden only at `gone`, after the store has written it, and the queue drops it in the same task: a row that
  // is painted is never hidden, and a hidden row is never painted.
  const offGone = machine.subscribe(
    (state) => state.state === "gone",
    (gone) => {
      if (gone) {
        props.toast.dismiss(props.item.id);
      }
    },
  );

  // the element exists only after the render: the start state's effect needs it, so the machine starts here, in an
  // effect that tracks nothing and runs once
  createEffect(
    () => undefined,
    () => {
      machine.start();
    },
  );

  onCleanup(() => {
    offRequest();
    offGone();
    offEffect();
    offCancel();
    machine.destroy();
  });

  const own = {
    "data-part": "toast",
    "data-tone": props.item.tone,
    get "data-state"() {
      return store.state.phase;
    },
    get hidden() {
      return view.hidden;
    },
    ref: (element: HTMLElement) => {
      row = element;
    },
    get class() {
      return css.cn(toast({ tone: props.item.tone }), props.class);
    },
  } as PartProps;
  return renderPart(
    props,
    merge(props.toast.toastProps(props.item.id), own),
    props.item,
    (part) => (
      <div {...part}>
        <p data-part="toast-title" class={titleClass}>
          {props.item.title}
        </p>
        <Show when={props.item.description !== undefined}>
          <p data-part="toast-description" class={descriptionClass}>
            {props.item.description}
          </p>
        </Show>
        <button
          type="button"
          data-part="toast-close"
          class={closeClass}
          aria-label="Dismiss"
          onClick={() => machine.send({ type: "dismiss" })}
        >
          <span aria-hidden="true">×</span>
        </button>
      </div>
    ),
  );
};

import type { JSX } from "@solidjs/web";
import { untrack } from "solid-js";

/**
 * What a part hands to `render`: the props the part owns (`id`, `aria-*`, `data-part`, `class`) and the state it is in, as
 * accessors — Solid does not re-render a component, so a snapshot would be dead on the second read.
 *
 * Base UI's `render` takes an element and clones it with the part's props; Solid cannot clone (JSX is already a node), so
 * the element form becomes the function form and a component is that function: `render={(props) => <a {...props} />}`,
 * `render={Button}`.
 */
export type Render<P extends object, S> = (props: P, state: S) => JSX.Element;

/**
 * What a part hands to `render`: element-generic attributes, because the element is the caller's (`<a>`, `<textarea>`, a
 * component). `ref` stays the caller's too — a part cannot type a ref for an element it has not chosen.
 */
export type PartProps = Omit<JSX.HTMLAttributes<HTMLElement>, "ref"> & {
  readonly class?: string;
};

/** A part that anything can render: `render` replaces its element and keeps the props the part owns. */
export interface Renderable<P extends object, S> {
  readonly render?: Render<P, S> | undefined;
}

/**
 * Renders a part: the caller's `render` when it gave one, the part's own element otherwise. `render` is structural, so it is
 * read once (untracked): a part that swapped it at run time would need a remount, not an update.
 *
 * @param {Renderable<P, S>} part the component's props, for the `render` it may carry
 * @param {P} props the part's props, already merged with the caller's own and with `class` and `data-part`
 * @param {S} state the part's state, as accessors
 * @param {(props: P) => JSX.Element} fallback the element the part is by default
 * @returns {JSX.Element} the part
 */
export const renderPart = <P extends object, S>(
  part: Renderable<PartProps, S>,
  props: P,
  state: S,
  fallback: (props: P) => JSX.Element,
): JSX.Element => {
  const render = untrack(() => part.render);
  // the part hands more than `PartProps` (its own element's attributes: `type` on a button, `value` on an input); a render
  // function is typed by what every part guarantees, and reads the rest as the DOM attributes they are
  return render === undefined ? fallback(props) : render(props as PartProps, state);
};

import { look } from "@cssints/mise-en-mode" with { type: "cssints" };
import { check, createGlobalTheme, createTokens, media } from "cssints" with { type: "cssints" };

import { darkTheme, forcedColorsTheme, lightTokens } from "./tokens.ts";

// The theme the starters are written against: one lightness scale, one hue and one chroma per
// colour family, and the semantic colours made of them. The data lives in tokens.ts, so the
// registry can compile it to a plain theme.css without the cssints plugin; this module is the
// same theme for the components and the demo page, with the contrast gate.
const t = createTokens(lightTokens);

// The dark mode is the lightness scale turned over, so every step and every colour made of it follows: the text is still
// gray-1200, it is just a light gray now. The page and the surface are the reference's own dark values, and the popover shadow
// deepens because a shadow on a dark page reads as a smudge.
createGlobalTheme(t, media("(prefers-color-scheme: dark)"), darkTheme);

// The same dark look as a scope a page can ask for: `<div data-mode="dark">` moves every token inside it, and a surface or a
// frame under it follows without a prop. It is a mise-en-mode look, so it is in the `app` layer: a host's `author` or `viewer`
// look over the same marker wins without a specificity trick, and `data-mode="dark/color"` moves the colours alone. The media
// query above stays a global theme: a look is a `data-mode` scope, and the system preference is not one.
look(t, "dark", "app", darkTheme);

// One preset, because the theme is neutral: the reference's indigo, as its two numbers. The others are in its theme.css.
createGlobalTheme(t, '[data-tint="indigo"]', {
  hue: { tint: "284.23" },
  chroma: { tint: "0.25049" },
});

// On a dense screen (200dpi and up) the targets grow: the spacing steps and the text with them, as in the reference.
createGlobalTheme(t, media("(min-resolution: 200dpi)"), {
  space: { base: "calc(0.25rem * 1.25)" },
  font: { sizeSm: "0.9375rem", size: "1.0625rem", sizeLg: "1.25rem" },
});

// Windows high contrast mode throws the theme away and paints the system's own colours; forced-colors makes that explicit,
// since a component that reads a token here gets the system colour rather than the tint.
createGlobalTheme(t, media("(forced-colors: active)"), forcedColorsTheme);

// The pairs a reader meets on every page: body text, the second level of text, and a link on a card. Both modes and every
// theme above are checked (the preset too, since it sets the tokens the link is made of), and a ratio under the floor fails
// the build. 7 for text and 4.5 for the rest are the WCAG 2.x AAA and AA floors.
check.contrast(t.color.text, t.color.page, { min: 7 }); // the tabs skin's selected label
check.contrast(t.color.muted, t.color.page, { min: 4.5 }); // its unselected label
check.contrast(t.color.link, t.color.surface, { min: 4.5 });
check.contrast(t.color.placeholder, t.color.page, { min: 4.5 });
check.contrast(t.color.onHighlight, t.color.highlight, { min: 4.5 });
// The active tab's underline is a graphic against the page: 3 is the WCAG 1.4.11 floor for non-text contrast. The dark
// mode is the closest (3.55:1 without the preset, 3.17:1 with indigo), so a lighter highlight would break it.
check.contrast(t.color.highlight, t.color.page, { min: 3 });
// The focus ring is a graphic, not text: 3 is the WCAG 1.4.11 floor for a non-text contrast.
check.contrast(t.color.focusRing, t.color.page, { min: 3 }); // the tabs skin's ring

export { t };

import { createToast, type Toast, type ToastOptions } from "@cssints/headless";
import { render } from "@solidjs/web";

import { Toaster } from "./toast.tsx";

/** What a mounted toaster hands the test: the controller, the dismissals it saw, and a teardown. */
export interface MountedToaster {
  readonly api: Toast;
  /** Every id the primitive says left, in order. */
  readonly dismissed: string[];
  readonly dispose: () => void;
}

/**
 * Mounts the styled toaster for the browser test: the page holds the controller, so the fixture plays the page. The stack is
 * portalled, so `host` is only where the `Toaster` itself is rendered (`document.body` by default) and the region lands in
 * `document.body` whatever `host` is.
 *
 * @param {ToastOptions} options what the queue is created with
 * @param {HTMLElement} host the element the `Toaster` is rendered into, for the transformed ancestor the test needs
 * @param {{ readonly reducedMotion?: boolean }} ui the skin's own props, so a test can turn the motion preference off
 * @returns {MountedToaster} the controller, the dismissals and the teardown
 */
export const mountToaster = (
  options: ToastOptions = {},
  host: HTMLElement = document.createElement("div"),
  ui: { readonly reducedMotion?: boolean } = {},
): MountedToaster => {
  document.body.append(host);
  const dismissed: string[] = [];
  let api!: Toast;

  const dispose = render(() => {
    api = createToast({
      ...options,
      onDismiss: (id) => {
        dismissed.push(id);
        options.onDismiss?.(id);
      },
    });
    return <Toaster toast={api} reducedMotion={ui.reducedMotion} />;
  }, host);

  return {
    api,
    dismissed,
    dispose: () => {
      dispose();
      host.remove();
    },
  };
};

import { type EffectHandle, harness } from "@cssints/machine";
import { createMachineStore } from "@cssints/machine/solid";
import { createMemo, createRoot, flush } from "solid-js";
import { afterEach, describe, expect, it } from "vite-plus/test";

import { type MountedToaster, mountToaster } from "./toast.fixture";
import { type ToastPhase, toastRowMachine } from "./toast.tsx";

/** Solid 2 applies setters and delivers delegated events on a later tick. */
const tick = (ms = 20): Promise<void> => new Promise((resolve) => setTimeout(resolve, ms));

/**
 * Polls until `done` holds and returns how long it took. Timers run late on a loaded machine, so a countdown is waited for,
 * never slept through.
 */
const waitFor = async (done: () => boolean, limit = 10_000): Promise<number> => {
  const start = Date.now();
  while (!done()) {
    if (Date.now() - start > limit) {
      throw new Error(`waitFor timed out after ${limit} ms`);
    }
    await tick();
  }
  return Date.now() - start;
};

const mounts: MountedToaster[] = [];

const mount = (
  options = {},
  host?: HTMLElement,
  ui: { readonly reducedMotion?: boolean } = {},
): MountedToaster => {
  const mounted = mountToaster(options, host, ui);
  mounts.push(mounted);
  return mounted;
};

afterEach(() => {
  for (const mounted of mounts.splice(0)) {
    mounted.dispose();
  }
});

// The stack is portalled, so the region is in `document.body`, not inside the element the fixture rendered into.
const stack = (): HTMLElement | null =>
  document.querySelector<HTMLElement>('[data-part="toast-region"]');

const rows = (): ReadonlyArray<HTMLElement> => [
  ...document.querySelectorAll<HTMLElement>('[data-part="toast"]'),
];

const rowOf = (title: string): HTMLElement | undefined =>
  rows().find((row) => row.querySelector('[data-part="toast-title"]')?.textContent === title);

const closeOf = (title: string): HTMLButtonElement | undefined =>
  rowOf(title)?.querySelector<HTMLButtonElement>('[data-part="toast-close"]') ?? undefined;

/** Every `data-state` a row is given, from the click to the unmount: the phases the DOM actually painted. */
const watchPhases = (
  row: HTMLElement,
): { readonly phases: string[]; readonly stop: () => void } => {
  const phases: string[] = [];
  const observer = new MutationObserver(() => {
    const phase = row.getAttribute("data-state");
    if (phase !== null) {
      phases.push(phase);
    }
  });
  observer.observe(row, { attributes: true, attributeFilter: ["data-state"] });
  return { phases, stop: () => observer.disconnect() };
};

// --- the protocol, on the harness: no browser, no real time -----------------------------------------------------------------
// The three properties the row's protocol has that an `open` signal cannot express: a dismissal during the enter reverses,
// a cancelled effect's completion is dropped by its handle id, and the second intent of a burst lands in a state that
// does not react to it. The harness starts the machine, so its enter effect is already issued and every delivery, effect
// and cancellation is logged.

const only = (h: { readonly machine: { effects(): readonly EffectHandle[] } }): EffectHandle => {
  const handles = h.machine.effects();
  expect(handles).toHaveLength(1);
  return handles[0] as EffectHandle;
};

describe("Toast x the row machine (the harness)", () => {
  it("reverses a dismiss during entering, and the leave ends gone", () => {
    const h = harness(toastRowMachine(false));
    expect(h.machine.getState().state).toBe("entering");
    const enter = only(h);
    expect(enter.spec.type).toBe("enter");

    h.send({ type: "dismiss" });
    expect(h.machine.getState().state).toBe("leaving");
    // leaving `entering` cancelled its effect and issued one leave: the box continues from where it was
    expect(h.cancelled()).toEqual([enter.id]);
    const leave = only(h);
    expect(leave.spec.type).toBe("leave");

    h.send({ type: "finish", id: leave.id });
    expect(h.machine.getState().state).toBe("gone");
    expect(h.machine.effects()).toHaveLength(0);
    // one departure, which is the one `onDismiss` the primitive hears
    expect(h.log.filter((entry) => entry.to === "gone")).toHaveLength(1);
  });

  it("ignores a cancelled enter's finish, so the row keeps leaving", () => {
    const h = harness(toastRowMachine(false));
    const enter = only(h);
    h.send({ type: "dismiss" });
    expect(h.machine.getState().state).toBe("leaving");
    const leave = only(h);

    // the cancelled animation's own rejection: the id it carries is no longer a live handle
    h.send({ type: "finish", id: enter.id });
    expect(h.machine.getState().state).toBe("leaving");
    expect(only(h).id).toBe(leave.id);
    expect(h.log.at(-1)).toMatchObject({ event: "finish", to: undefined, cancelled: true });
  });

  it("does not restart a leave that is already running", () => {
    const h = harness(toastRowMachine(false));
    h.send({ type: "dismiss" });
    const leave = only(h);

    h.send({ type: "dismiss" });
    expect(h.machine.getState().state).toBe("leaving");
    expect(only(h).id).toBe(leave.id);
    // the second intent was dropped, not queued: leaving is the state that coalesces the burst
    expect(
      h.log.filter((entry) => entry.event === "dismiss" && entry.effect !== undefined),
    ).toHaveLength(1);
  });

  it("two dismisses in one frame produce one effect and one departure", () => {
    const h = harness(toastRowMachine(false));
    // a close click twice, before a frame has passed: the second lands in `leaving`
    h.race({ type: "dismiss" }, { type: "dismiss" });
    const leave = only(h);
    h.send({ type: "finish", id: leave.id });

    expect(h.machine.getState().state).toBe("gone");
    expect(
      h.log.filter((entry) => entry.event === "dismiss" && entry.effect !== undefined),
    ).toHaveLength(1);
    expect(h.log.filter((entry) => entry.to === "gone")).toHaveLength(1);
  });

  it("takes the timeout's dismiss and a close click in the same frame as one dismissal", () => {
    const h = harness(toastRowMachine(false));
    // the countdown is the primitive's; its expiry reaches the row as the same `dismiss` a click sends
    h.race({ type: "dismiss" }, { type: "dismiss" });
    const leave = only(h);
    h.send({ type: "finish", id: leave.id });

    expect(h.machine.getState().state).toBe("gone");
    expect(h.log.filter((entry) => entry.to === "gone")).toHaveLength(1);
    // and nothing asked again once the row was gone
    h.send({ type: "dismiss" });
    expect(h.machine.getState().state).toBe("gone");
    expect(
      h.log.filter((entry) => entry.event === "dismiss" && entry.effect !== undefined),
    ).toHaveLength(1);
  });

  it("skips entering and leaving when the preference asks for no motion", () => {
    const h = harness(toastRowMachine(true));
    // the machine is built at `visible`: no enter effect exists to cancel
    expect(h.machine.getState().state).toBe("visible");
    expect(h.machine.effects()).toHaveLength(0);

    h.send({ type: "dismiss" });
    expect(h.machine.getState().state).toBe("gone");
    // one transition, no effect, and no phase in between
    expect(h.log.every((entry) => entry.effect === undefined)).toBe(true);
    expect(h.log.map((entry) => entry.from)).toEqual(["visible"]);
  });
});

